import unittest
from slugify import slugify
class SlugifyTests(unittest.TestCase):
    def test_empty(self): self.assertEqual(slugify(""), "")
    def test_case(self): self.assertEqual(slugify("MiXeD"), "mixed")
    def test_whitespace(self): self.assertEqual(slugify("  One \t Two   "), "one-two")
